<?php include "../includes/cek_session.php";include "../config/koneksi.php";hanya_role('Administrator');$id=(int)($_GET['id']??0);$p=mysqli_fetch_assoc(mysqli_query($koneksi,"SELECT * FROM tb_pelanggan WHERE id_pelanggan=$id"));if(!$p){header("Location:index.php");exit;}$title="Edit Pelanggan";include "../includes/header.php";if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['nama_pelanggan']);$hp=trim($_POST['no_hp']);$a=trim($_POST['alamat']);$st=mysqli_prepare($koneksi,"UPDATE tb_pelanggan SET nama_pelanggan=?,no_hp=?,alamat=? WHERE id_pelanggan=?");mysqli_stmt_bind_param($st,"sssi",$n,$hp,$a,$id);if(mysqli_stmt_execute($st)){header("Location:index.php");exit;}}?>
